args.content:
:root {
  color-scheme: light;
  font-family: Georgia, "Times New Roman", serif;
}

body {
  max-width: 720px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
  line-height: 1.6;
  color: #1b1b1b;
  background: #faf8f4;
}

header {
  margin-bottom: 2rem;
  border-bottom: 1px solid #ddd6c9;
  padding-bottom: 1.25rem;
}

h1 {
  margin: 0 0 0.25rem;
  font-size: 2rem;
  letter-spacing: 0.01em;
}

.tagline {
  margin: 0;
  color: #4a4a4a;
  font-style: italic;
}

h2 {
  font-size: 1.15rem;
  margin-top: 2.25rem;
  border-left: 3px solid #8a6d3b;
  padding-left: 0.6rem;
}

a {
  color: #6b4f24;
}

nav a {
  margin-right: 1rem;
  font-weight: bold;
}

footer {
  margin-top: 3rem;
  font-size: 0.85rem;
  color: #777;
  border-top: 1px solid #ddd6c9;
  padding-top: 1rem;
}

.entry {
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px dashed #ddd6c9;
}

.deadline {
  font-weight: bold;
}

.source {
  font-size: 0.9rem;
}

.note {
  background: #f1ece0;
  border: 1px solid #ddd6c9;
  padding: 0.75rem 1rem;
  font-size: 0.92rem;
}
